package services

import (
	"context"
	"errors"
	"io"
	"regexp"
	"strings"

	"backend-yonathan/src/pkg/apiresponse"
	"backend-yonathan/src/pkg/constants"

	"cloud.google.com/go/storage"
	"github.com/gofiber/fiber/v3"
)

// mediaNamePattern only accepts object names generated by UploadImage (uuid.ext),
// so the endpoint cannot be used to read arbitrary bucket paths.
var mediaNamePattern = regexp.MustCompile(`^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpe?g|png|gif|webp)$`)

// errMediaNotFound signals a missing object to the handler.
var errMediaNotFound = errors.New("media not found")

// readMediaFunc is injectable for tests. Default: readGCSObject.
var readMediaFunc = readGCSObject

// readGCSObject reads a whole object (uploads are capped at 5 MB) and its content type.
func readGCSObject(ctx context.Context, bucketName, objectPath string) ([]byte, string, error) {
	client, err := storage.NewClient(ctx)
	if err != nil {
		return nil, "", err
	}
	defer client.Close()

	reader, err := client.Bucket(bucketName).Object(objectPath).NewReader(ctx)
	if errors.Is(err, storage.ErrObjectNotExist) {
		return nil, "", errMediaNotFound
	}
	if err != nil {
		return nil, "", err
	}
	defer reader.Close()

	data, err := io.ReadAll(io.LimitReader(reader, constants.MaxImageUploadBytes+1))
	if err != nil {
		return nil, "", err
	}
	return data, reader.Attrs.ContentType, nil
}

// ServePublicImage godoc
// @Summary      Imagen pública estable
// @Description  Sirve una imagen subida vía upload-image con URL permanente y cacheable. Pensado para og:image / twitter:image, que no admiten URLs firmadas que expiran.
// @Tags         Media
// @Produce      image/jpeg,image/png,image/gif,image/webp
// @Param        name     path   string  true   "Nombre del objeto (uuid.ext)"
// @Param        variant  query  string  false  "og: recorte 1200x630 JPEG para tarjetas sociales"
// @Success      200
// @Failure      404   {object}  map[string]interface{}
// @Router       /api/media/{name} [get]
func ServePublicImage(c fiber.Ctx) error {
	name := strings.ToLower(c.Params("name"))
	bucket := constants.GCSBucketName()
	if bucket == "" || !mediaNamePattern.MatchString(name) {
		return apiresponse.Error(c, fiber.StatusNotFound, "media_not_found", "Imagen no encontrada", nil)
	}

	data, contentType, err := readMediaFunc(c.Context(), bucket, constants.StorageImagePrefix+"/"+name)
	if errors.Is(err, errMediaNotFound) {
		return apiresponse.Error(c, fiber.StatusNotFound, "media_not_found", "Imagen no encontrada", nil)
	}
	if err != nil {
		return apiresponse.Error(c, fiber.StatusBadGateway, "media_read_failed", "No se pudo leer la imagen", err.Error())
	}
	if !isAllowedImageContentType(contentType) {
		return apiresponse.Error(c, fiber.StatusNotFound, "media_not_found", "Imagen no encontrada", nil)
	}

	if c.Query("variant") == "og" {
		rendered, renderErr := cachedOGImage(name, data)
		if renderErr == nil {
			data, contentType = rendered, "image/jpeg"
		}
	}

	c.Set(fiber.HeaderContentType, contentType)
	c.Set(fiber.HeaderCacheControl, constants.PublicMediaCacheControl)
	c.Set("X-Content-Type-Options", "nosniff")
	// helmet fija CORP same-origin para toda la API; estas imágenes deben poder
	// embeberse desde el sitio y desde los previsualizadores de redes sociales.
	c.Set(fiber.HeaderCrossOriginResourcePolicy, "cross-origin")
	return c.Send(data)
}
